        o.set("parent", compact_symbol_reference(host, parent)?);
    }
    if let Some(export_symbol) = symbol.export_symbol() {
        o.set("exportSymbol", compact_symbol_reference(host, export_symbol)?);
    }
    Ok(o.build())
}

