async fn readonly(&self, listed: (u64, Listing), properties: &[SymbolInfo]) -> Result<Arc<[bool]>, CallError> {
    if let Some(settled) = properties.iter().map(|property| property.readonly).collect::<Option<Arc<[bool]>>>() {
